import java.util.Scanner;

public class P233A {
    public static void main(String[] args) {

        Scanner scn = new Scanner(System.in);
        int n = scn.nextInt();
        int [] arr = new int[n];

        if(n % 2 != 0){

            System.out.println(-1);
        }

        else{

            for(int i = 0; i < n; i++){

                if((i + 1) % 2 == 0){

                    arr[i] = i;
                }
                else{
                    arr[i] = i + 2;
                }
            }

            for(int val : arr){
                System.out.println(val + "");
            }
        }
    }
}
